insert into public.decisions
  (number, statement, reason, status, decided_by_name, decided_at, origin, origin_ref)
overriding system value
values
  (207, 'Changes to slice 3.1 after an independent review, before it merged. Paths are matched by the API''s own glob reader (`*`, `**`, `?`, everything else literal), whose time grows only with the pattern times the path, and the contract refuses braces, brackets and extglobs; a pattern matches a path or anything under it, and one without `/` matches at any depth. A word must be at least three characters, and text is split on whitespace to find paths. An area''s owner may act on a proposal only if they owned the area when it was proposed (`owner_since`), since anyone may change an owner. Naming a change''s areas and queueing its posts is one transaction, with at most ten mentions a post. Routing a brief or a decision never fails the tool call; a pull request with no area does not ask GitHub for its files. Renaming an area relabels only its own workspace''s decisions, and two renames to one name at once refuse the second. The owner line comes first in a decision''s post. A queued post that no longer parses is set aside, not left to hold up the thread', 'The review found that a person could make themselves owner of an area and confirm the proposals already waiting in it, that Node''s glob matching can be made slow by a pattern anyone may write, that a lost post could leave an area named but never said, that a rename relabelled other workspaces'' decisions, and that one bad row in the queue blocked every later post. Each now has a test', 'active', 'the owner', '2026-11-25T00:00:00Z', 'import', '207')
on conflict (origin, origin_ref) where origin_ref is not null do nothing;
